<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Auth\AuthenticationException;use Illuminate\Http\Request;use Illuminate\Validation\ValidationException;use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;use Throwable;
class MobileApiEnvelope{public function handle(Request $request,Closure $next){try{return$next($request);}catch(ValidationException $e){return response()->json(['error'=>['code'=>'validation_failed','message'=>'Please check the highlighted fields.','fields'=>$e->errors()]],422);}catch(AuthenticationException){return response()->json(['error'=>['code'=>'unauthenticated','message'=>'Please sign in to continue.']],401);}catch(HttpExceptionInterface $e){$status=$e->getStatusCode();$code=match($status){403=>'forbidden',404=>'not_found',409=>'conflict',410=>'gone',429=>'rate_limited',default=>'request_failed'};return response()->json(['error'=>['code'=>$code,'message'=>$e->getMessage()?:'The request could not be completed.']],$status);}catch(Throwable $e){report($e);return response()->json(['error'=>['code'=>'server_error','message'=>'Something went wrong. Please try again.']],500);}}}
